from copy import deepcopy


def empty_state():
    return {'stock': {}, 'requests': {}, 'seen': {}}


def apply_event(state, event):
    result = deepcopy(state)
    stock, requests, seen = result['stock'], result['requests'], result['seen']
    event_id = event['id']
    if event_id in seen:
        if seen[event_id] != event:
            raise ValueError('conflicting event id')
        return result
    if event['op'] == 'restock':
        stock[event['sku']] = stock.get(event['sku'], 0) + event['qty']
    elif event['op'] == 'reserve':
        request = event['request']
        lines = dict(event['lines'])
        if request in requests or any(sku not in stock or stock[sku] < qty for sku, qty in lines.items()):
            raise ValueError('cannot reserve')
        for sku, qty in lines.items():
            stock[sku] -= qty
        requests[request] = lines
    else:
        request = event['request']
        if request not in requests:
            raise ValueError('inactive request')
        for sku, qty in requests[request].items():
            stock[sku] += qty
        del requests[request]
    seen[event_id] = deepcopy(event)
    return result
